<template>
  <ResearchShell section="market" @new-analysis="router.push('/chart-lab')"><div class="market-lab">
    <header class="market-breadcrumb">Market research <RouterLink to="/chart-lab">Back to Chart Lab</RouterLink></header>
    <main>
      <section class="heading"><div><p class="eyebrow">BTC multi-strategy research</p><h1>Inspect the whole market view.</h1><p>Measured inputs, competing strategy families and an auditable record of what worked.</p></div><span class="mode">Paper research</span></section>
      <div class="controls"><label>Market<select v-model="symbol"><option v-for="s in ['BTCUSDT','ETHUSDT','SOLUSDT','XRPUSDT']" :key="s">{{ s }}</option></select></label><label>Candle interval<select v-model="interval"><option v-for="tf in timeframes" :key="tf">{{ tf }}</option></select></label><label>Forecast horizon<select v-model="horizon"><option v-for="tf in timeframes" :key="tf">{{ tf }}</option></select></label><button class="primary" @click="start('snapshot')" :disabled="busy">{{ busy ? 'Research running…' : 'Refresh market analysis' }}</button></div>
      <p v-if="error" class="error" role="alert">{{ error }}</p>
      <div v-if="job?.status==='running'" class="progress" role="status"><span class="pulse"></span>{{ job.stage }}<small>You can refresh the page; this job is saved.</small></div>
      <div v-if="job?.status==='failed'||job?.status==='interrupted'" class="error">{{ job.error || job.stage }}</div>
      <section class="metrics"><div><span>Strategy library</span><strong>{{ catalog.length || 184 }}</strong><small>{{ familyNames.length || 15 }} families</small></div><div><span>Available in snapshot</span><strong>{{ current ? activeCount : '—' }}</strong><small>Missing inputs cause abstention</small></div><div><span>Current regime</span><strong class="regime">{{ current?.features.regime || 'Awaiting data' }}</strong><small>{{ current ? date(current.snapshot_as_of) : 'Refresh to collect public market data' }}</small></div><div><span>Historical evaluation</span><strong>{{ latestBenchmark?.prediction_count?.toLocaleString() || '—' }}</strong><small>Held-out numerical forecasts</small></div></section>
      <div class="market-workbench"><nav class="market-section-nav" aria-label="Research sections"><template v-for="item in tabs" :key="item.id"><span v-if="['market','agents','backtests'].includes(item.id)" class="market-nav-group">{{ item.id==='market'?'Research':item.id==='agents'?'Agents & simulation':'Validation' }}</span><button :class="{selected:tab===item.id}" :aria-current="tab===item.id?'page':undefined" @click="tab=item.id">{{ item.name }}</button></template></nav><div class="market-report">

      <section v-if="tab==='market'" class="panel">
        <div class="panel-heading"><h2>{{ current?.symbol || symbol }} market snapshot</h2><span>{{ current?.interval }} closed candles</span></div>
        <template v-if="current"><div class="market-observed-workspace"><div><svg class="price-chart" viewBox="0 0 900 300" role="img" aria-label="Recent observed closing prices"><path :d="pricePath"/><text x="14" y="25">{{ format(current.features.values.close) }} USDT</text><text x="14" y="287">{{ date(current.candles[0]?.close_time) }}</text><text x="600" y="287">{{ date(current.candles.at(-1)?.close_time) }}</text></svg><p class="hint">Observed closes from the selected interval. The final incomplete candle is excluded.</p><div class="facts-grid"><div v-for="key in ['atr','rsi','adx','vwap','volume_delta','funding_rate','open_interest','basis','spread_bps','book_imbalance']" :key="key"><span>{{ label(key) }}</span><strong>{{ format(current.features.values[key]) }}</strong></div></div></div><MarketAgentMap :specialists="specialists" :catalog="catalog" :snapshot="current"/></div><div class="two-columns market-coverage"><div><h3>Measured timeframes</h3><div v-for="(values,timeframe) in current.features.timeframes||{}" :key="timeframe" class="coverage-row"><span>{{ timeframe }} · {{ date(values.close_time) }}</span><span>RSI {{ format(values.rsi) }}</span></div></div><div><h3>Source coverage</h3><div v-for="(source,key) in current.features.coverage" :key="key" class="coverage-row"><span>{{ label(key) }}</span><span :class="source.status">{{ source.status }}</span></div><h3 class="spaced">Known limits</h3><ul class="muted"><li v-for="item in current.features.limitations" :key="item">{{ item }}</li></ul></div></div><details><summary>Macroeconomic sources</summary><p class="hint">{{ current.features.macro?.scope }}</p><article v-for="item in current.features.macro?.items||[]" :key="item.url" class="news"><a :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.title }}</a><small>{{ item.publisher }} · published {{ date(item.published_at) }}</small><p>{{ item.excerpt }}</p></article></details></template>
        <EmptyState v-else />
      </section>

      <section v-else-if="tab==='prediction'" class="panel"><h2>Forecast and competing families</h2><template v-if="current"><div v-if="current.quant" class="quant-card"><h3>Statistical forecast · {{ current.quant.horizon }}</h3><div class="probabilities"><div v-for="(value,key) in current.quant.probabilities" :key="key"><span>{{ key }}</span><strong>{{ (value*100).toFixed(1) }}%</strong></div></div><p>{{ current.quant.probability_note }}</p><p class="notice">{{ current.quant.benchmark?.comparison?.finding }}</p><p class="hint">Issued {{ date(current.quant.issued_at) }} · target {{ date(current.quant.prediction_end) }} · {{ Date.now()>current.quant.prediction_end ? 'Target time passed' : 'Outcome pending' }}</p></div><p v-else class="notice">No fitted model is available for this interval and horizon. Train it in Backtests before displaying statistical probabilities.</p><h3>Family signals</h3><p class="hint">Scores describe rule hypotheses, not probabilities. Each family has equal initial influence; duplicate agent names cannot add votes.</p><div v-for="family in current.consensus.families" :key="family.family" class="family-row"><span>{{ label(family.family) }}</span><div class="score-track"><i :style="scoreStyle(family.score)"></i></div><strong>{{ signed(family.score) }}</strong><small>{{ family.active_count }} active</small></div><p class="hint">Disagreement: {{ format(current.consensus.disagreement) }}. The model has not established that agreement predicts accuracy.</p></template><EmptyState v-else /></section>

      <section v-else-if="['strategies','ict','ta','orderflow','derivatives'].includes(tab)" class="panel"><div class="panel-heading"><h2>{{ tabs.find(t=>t.id===tab)?.name }}</h2><span>{{ filteredStrategies.length }} profiles</span></div><div class="filters"><input v-model="search" placeholder="Search strategies or required inputs" aria-label="Search strategies"><select v-if="tab==='strategies'" v-model="familyFilter" aria-label="Filter by family"><option value="">All families</option><option v-for="f in familyNames" :key="f" :value="f">{{ label(f) }}</option></select><label class="inline-check"><input type="checkbox" v-model="availableOnly">Available only</label></div><p class="hint">These are operational, testable strategy definitions. A named profile is not evidence that the trading philosophy is profitable.</p><div class="table-scroll"><table><thead><tr><th>Strategy</th><th>Family</th><th>Status</th><th>Signal</th><th>Details</th></tr></thead><tbody><tr v-for="item in filteredStrategies" :key="item.id"><td>{{ item.name }}</td><td>{{ label(item.family) }}</td><td><span :class="item.status">{{ item.status || 'Registered' }}</span></td><td>{{ item.direction || '—' }}<small v-if="item.score!=null">{{ signed(item.score) }}</small></td><td><details><summary>Inspect</summary><p>{{ item.rule }}</p><p v-if="item.missing?.length"><strong>Missing:</strong> {{ item.missing.join(', ') }}</p><pre v-if="item.features_used">{{ JSON.stringify(item.features_used,null,2) }}</pre></details></td></tr></tbody></table></div></section>

      <section v-else-if="tab==='agents'" class="panel"><h2>Specialist map & dependencies</h2><p class="hint">Inspect each registered role and the evidence its strategy family requires.</p><MarketAgentMap :specialists="specialists" :catalog="catalog" :snapshot="current"/><div class="specialists"><article v-for="role in specialists" :key="role.id"><h3>{{ role.name }}</h3><span>{{ label(role.family) }}</span><p>{{ role.focus }}</p><small>Requires: {{ label(role.capability) }}</small></article></div><h3 class="spaced">Strategy dependency map</h3><div class="filters"><select v-model="selectedStrategy" aria-label="Inspect strategy dependencies"><option v-for="item in catalog" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div v-if="chosenStrategy" class="dependency-map"><div class="node family-node">{{ label(chosenStrategy.family) }}</div><span>contains</span><div class="node strategy-node">{{ chosenStrategy.name }}</div><span>uses</span><div class="feature-nodes"><div v-for="need in chosenStrategy.needs" :key="need" class="node">{{ label(need) }}</div></div></div><p class="hint">Edges reflect the stored rules and input requirements. They do not imply measured statistical independence.</p></section>

      <section v-else-if="tab==='simulation'" class="panel"><h2>Scenario simulation</h2><template v-if="current"><p class="notice">{{ current.simulation.paths.toLocaleString() }} simulated paths · {{ current.horizon }} · seed {{ current.simulation.seed }}. Frequencies describe the simulator, not validated market probabilities.</p><svg class="fan-chart" viewBox="0 0 900 360" role="img" aria-label="Simulated price distribution"><path class="outer-band" :d="fanBand(.1,.9)"/><path class="inner-band" :d="fanBand(.25,.75)"/><path class="median-line" :d="fanMedian"/><text x="15" y="25">{{ format(current.simulation.initial_price) }} starting reference</text></svg><div class="facts-grid"><div v-for="(value,key) in current.simulation.terminal_price_quantiles" :key="key"><span>{{ key }} terminal price</span><strong>{{ format(value) }}</strong></div></div><p class="hint">Terminal price quantiles differ from the highest or lowest price visited during a path.</p><div class="two-columns spaced"><div><h3>First simulated path</h3><div class="table-scroll"><table><thead><tr><th>Step</th><th>Action</th><th>Demand</th><th>Price</th></tr></thead><tbody><tr v-for="event in current.simulation.first_path_actions" :key="event.step"><td>{{ event.step }}</td><td>{{ event.action }}</td><td>{{ signed(event.participant_demand) }}</td><td>{{ format(event.simulated_price) }}</td></tr></tbody></table></div></div><div><h3>Virtual exchange activity</h3><p class="hint">Price formation: {{ label(current.simulation.price_formation || 'legacy illustration') }}.</p><a v-if="current.simulation.path_archive" :href="`${api}/api/market/runs/${current.id}/paths`">Download all simulated paths and ledgers</a><p class="hint">{{ current.simulation.execution?.scope || 'No order book available.' }}</p><pre v-if="current.simulation.execution">{{ JSON.stringify(current.simulation.execution,null,2) }}</pre><ul class="muted"><li v-for="item in current.simulation.limitations" :key="item">{{ item }}</li></ul></div></div></template><EmptyState v-else /></section>

      <section v-else-if="tab==='history'" class="panel"><div class="panel-heading"><h2>Stored forecasts</h2><button @click="loadPredictions">Refresh</button></div><p class="hint">Numerical forecasts are saved before the slower specialist discussion. Outcomes are separate records; original forecasts are never overwritten.</p><div class="table-scroll"><table><thead><tr><th>Issued</th><th>Horizon</th><th>Down</th><th>Flat</th><th>Up</th><th>Target time</th></tr></thead><tbody><tr v-for="item in predictions" :key="item.id"><td>{{ date(item.issued_at) }}</td><td>{{ item.horizon }}</td><td>{{ pct(item.probabilities.down) }}</td><td>{{ pct(item.probabilities.flat) }}</td><td>{{ pct(item.probabilities.up) }}</td><td>{{ date(item.prediction_end) }}</td></tr></tbody></table></div><p v-if="!predictions.length" class="hint">No numerical forecasts have been issued yet. A matching fitted model and a fresh market snapshot are required.</p></section>

      <section v-else-if="['backtests','comparison','calibration'].includes(tab)" class="panel"><div class="panel-heading"><h2>{{ tabs.find(t=>t.id===tab)?.name }}</h2><select v-if="benchmarks.length" v-model="benchmarkId" aria-label="Choose benchmark"><option v-for="b in benchmarks" :key="b.id" :value="b.id">{{ b.interval }} → {{ b.horizon }} · {{ b.prediction_count.toLocaleString() }} · {{ date(b.created_at) }}</option></select></div><div v-if="tab==='backtests'" class="benchmark-controls"><label>Held-out forecasts<input type="number" v-model.number="predictionCount" min="100" max="50000" step="1000"></label><label>Calibration<select v-model="calibrationMethod"><option value="isotonic">Isotonic</option><option value="platt">Platt</option><option value="temperature">Temperature</option></select></label><button class="primary" @click="start('backtest')" :disabled="busy">Run chronological benchmark</button></div><template v-if="selectedBenchmark"><p class="notice">{{ selectedBenchmark.comparison.finding }}</p><p class="hint">{{ selectedBenchmark.scope }}</p><div class="table-scroll"><table><thead><tr><th>Model</th><th>Forecasts</th><th>Accuracy</th><th>Brier ↓</th><th>Log loss ↓</th><th>Calibration error ↓</th></tr></thead><tbody><tr v-for="(score,name) in selectedBenchmark.metrics" :key="name"><td>{{ label(name) }}</td><td>{{ score.n.toLocaleString() }}</td><td>{{ pct(score.accuracy) }}</td><td>{{ score.brier_score.toFixed(4) }}</td><td>{{ score.log_loss.toFixed(4) }}</td><td>{{ score.calibration_error.toFixed(4) }}</td></tr></tbody></table></div><template v-if="tab==='calibration'"><h3 class="spaced">UP-probability reliability</h3><p class="hint">The diagonal is perfect calibration. Points are observed outcomes in held-out probability bins.</p><svg class="reliability-chart" viewBox="0 0 500 330" role="img" aria-label="Observed versus predicted UP probability"><path d="M45 280 L455 25" class="reference"/><path :d="reliabilityPath" class="actual"/><circle v-for="bin in reliabilityBins" :key="bin.lower" :cx="45+410*bin.predicted" :cy="280-255*bin.observed" r="5"><title>{{ bin.count }} forecasts; predicted {{ pct(bin.predicted) }}, observed {{ pct(bin.observed) }}</title></circle><text x="130" y="317">Predicted probability</text><text x="4" y="20">Observed</text></svg></template><h3 class="spaced">Validation boundaries</h3><ul class="muted"><li v-for="item in selectedBenchmark.limitations" :key="item">{{ item }}</li></ul><p class="hint">Not evaluated in this dataset: {{ selectedBenchmark.excluded_ablations.join(', ') }}.</p><details><summary>Chronological folds and execution assumptions</summary><pre>{{ JSON.stringify({folds:selectedBenchmark.folds,trading:selectedBenchmark.trading},null,2) }}</pre></details><button class="text-button" @click="download(selectedBenchmark,'benchmark')">Download benchmark</button></template><p v-else class="hint">Run a benchmark to fit and evaluate the numerical models. No performance numbers are fabricated.</p></section>

      <section v-else-if="tab==='settings'" class="panel"><h2>Research settings</h2><div class="settings"><label>Simulation paths<input type="number" min="10" max="5000" step="100" v-model.number="paths"></label><label class="inline-check"><input type="checkbox" v-model="includeMacro">Fetch official Federal Reserve and ECB releases</label></div><p class="hint">Database: {{ database }}. Optional PostgreSQL uses MIROBTC_DATABASE_URL on the backend. Collection happens when you start a research job.</p><p class="notice">No live trading orders are submitted. Numerical models, chart interpretations and simulated scenarios are evaluated separately.</p><h3>Model and data status</h3><ul class="muted"><li>LightGBM, XGBoost, logistic regression and random forest can be fitted by the benchmark.</li><li>Model-specific and specialist inputs that are absent remain unavailable.</li><li>Historical L2, options, ETF, on-chain and cross-market inputs require their own data; none is reconstructed from a screenshot.</li><li>New model searches must reserve fresh validation data; repeated testing on the same holdout does not prove improvement.</li></ul><ResearchTools :busy="busy" :symbol="symbol" :job="job" @start="start" /></section>
      </div></div>
      <footer><button v-if="current" class="text-button" @click="download(current,'market-run')">Download this market run</button><span>Prices and sources are snapshots. This research has not established a profitable trading system.</span></footer>
    </main>
  </div></ResearchShell>
</template>

<script setup>
import ResearchShell from '../components/ResearchShell.vue'
import { computed, defineComponent, h, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import ResearchTools from '../components/ResearchTools.vue'
import MarketAgentMap from '../components/MarketAgentMap.vue'
const route=useRoute(),router=useRouter()
const api=(import.meta.env.VITE_API_BASE_URL||'http://127.0.0.1:5001').replace(/\/$/,'')
const EmptyState=defineComponent({setup:()=>()=>h('div',{class:'empty'},[h('h3','Collect a market snapshot'),h('p','Choose an interval and horizon, then refresh the analysis. The source timestamps and unavailable inputs will be shown here.')])})
const tabs=[['market','Market snapshot'],['prediction','Prediction'],['strategies','Strategy war room'],['ict','ICT / SMC'],['ta','Support & resistance'],['orderflow','Order flow'],['derivatives','Derivatives'],['agents','Agent map'],['simulation','Simulation'],['history','Forecast history'],['backtests','Backtests'],['calibration','Calibration'],['comparison','Model comparison'],['settings','Settings']].map(([id,name])=>({id,name}))
const timeframes=['1m','3m','5m','15m','30m','1h','2h','4h','6h','12h','1d','1w']
const tab=computed({get:()=>tabs.some(x=>x.id===route.query.view)?route.query.view:'market',set:value=>router.push({query:{...route.query,view:value}})})
const symbol=ref('BTCUSDT'),interval=ref('15m'),horizon=ref('15m'),paths=ref(500),includeMacro=ref(true),predictionCount=ref(10000),calibrationMethod=ref('isotonic')
const current=ref(null),catalog=ref([]),specialists=ref([]),benchmarks=ref([]),benchmarkId=ref(''),database=ref(''),job=ref(null),error=ref(''),submitting=ref(false),predictions=ref([])
const search=ref(''),familyFilter=ref(''),availableOnly=ref(false),selectedStrategy=ref('ict_liquidity_sweep')
let pollTimer,disposed=false
const busy=computed(()=>submitting.value||job.value?.status==='running')
const familyNames=computed(()=>[...new Set(catalog.value.map(x=>x.family))])
const activeCount=computed(()=>current.value?.strategies.filter(x=>x.status==='active').length||0)
const latestBenchmark=computed(()=>benchmarks.value[0])
const selectedBenchmark=computed(()=>benchmarks.value.find(b=>b.id===benchmarkId.value)||latestBenchmark.value)
const chosenStrategy=computed(()=>catalog.value.find(s=>s.id===selectedStrategy.value))
const filteredStrategies=computed(()=>{
 const fixed={ict:'ICT_SMC_Liquidity',ta:'Traditional_Technical_Analysis',orderflow:'Order_Flow_Footprint',derivatives:'Derivatives_Leverage'}[tab.value]
 return (current.value?.strategies||catalog.value).filter(s=>(!fixed||s.family===fixed)&&(!familyFilter.value||fixed||s.family===familyFilter.value)&&(!availableOnly.value||s.status==='active')&&`${s.name} ${s.needs.join(' ')}`.toLowerCase().includes(search.value.toLowerCase()))
})
const label=s=>String(s||'').replaceAll('_',' ')
const format=x=>x==null?'Unavailable':Number(x).toLocaleString('en-US',{maximumFractionDigits:6})
const signed=x=>`${Number(x)>=0?'+':''}${Number(x).toFixed(3)}`
const pct=x=>`${(x*100).toFixed(1)}%`
const date=x=>x?new Date(x).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'—'
const scoreStyle=x=>({left:`${Math.min(50,50+x*50)}%`,width:`${Math.abs(x)*50}%`,background:x<0?'#a84931':'#42705b'})
const linePath=(values,width=900,height=300)=>{if(!values?.length)return'';const lo=Math.min(...values),span=Math.max(1e-8,Math.max(...values)-lo);return values.map((v,i)=>`${i?'L':'M'}${15+i*(width-30)/Math.max(1,values.length-1)},${height-45-(v-lo)*(height-90)/span}`).join(' ')}
const pricePath=computed(()=>linePath(current.value?.candles.map(c=>c.close)))
const fanPoints=(key)=>{const fan=current.value?.simulation.fan||[];const lo=Math.min(...fan.map(x=>x.p10)),hi=Math.max(...fan.map(x=>x.p90)),span=Math.max(hi-lo,1e-8);return fan.map((point,i)=>[15+i*870/Math.max(1,fan.length-1),325-(point[key]-lo)*270/span])}
const fanMedian=computed(()=>fanPoints('median').map(([x,y],i)=>`${i?'L':'M'}${x},${y}`).join(' '))
const fanBand=(lower,upper)=>{const points=[...fanPoints(`p${lower*100}`),...fanPoints(`p${upper*100}`).reverse()];return points.map(([x,y],i)=>`${i?'L':'M'}${x},${y}`).join(' ')+'Z'}
const reliabilityBins=computed(()=>selectedBenchmark.value?.metrics.hybrid.reliability.filter(x=>x.label==='up').sort((a,b)=>a.predicted-b.predicted)||[])
const reliabilityPath=computed(()=>reliabilityBins.value.map((bin,i)=>`${i?'L':'M'}${45+410*bin.predicted},${280-255*bin.observed}`).join(' '))
async function request(path,options){const response=await fetch(`${api}/api/market${path}`,options),data=await response.json();if(!response.ok||data.success===false)throw new Error(data.error||'Research request failed');return data}
async function load(){try{const [state,definitions]=await Promise.all([request('/state'),request('/catalog')]);if(disposed)return;current.value=route.query.run?(await request(`/runs/${route.query.run}`)).run:state.latest;benchmarks.value=state.benchmarks;database.value=state.database;catalog.value=definitions.strategies;specialists.value=definitions.specialists;if(!benchmarkId.value)benchmarkId.value=state.benchmarks[0]?.id||'';if(route.query.job)poll(String(route.query.job));else if(state.active_jobs.length)poll(state.active_jobs[0]);await loadPredictions()}catch(e){error.value=e.message}}
async function start(kind,extra={}){if(busy.value)return;error.value='';submitting.value=true;try{const result=await request('/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,options:{symbol:symbol.value,interval:interval.value,horizon:horizon.value,paths:paths.value,predictions:predictionCount.value,calibration:calibrationMethod.value,include_macro:includeMacro.value,...extra}})});await router.replace({query:{job:result.id}});poll(result.id)}catch(e){error.value=e.message}finally{submitting.value=false}}
async function poll(id){clearTimeout(pollTimer);try{const response=await request(`/jobs/${id}`);if(disposed)return;job.value=response.job;if(job.value.status==='running')pollTimer=setTimeout(()=>poll(id),2000);else if(job.value.status==='complete'){if(job.value.kind==='snapshot')current.value=job.value.result;else if(job.value.kind==='backtest'){benchmarks.value=[job.value.result,...benchmarks.value.filter(b=>b.id!==job.value.result.id)];benchmarkId.value=job.value.result.id;tab.value='backtests'}else if(['train_model','record','discovery'].includes(job.value.kind)){tab.value='settings'}loadPredictions()}}catch(e){if(!disposed){error.value=e.message;pollTimer=setTimeout(()=>poll(id),5000)}}}
async function loadPredictions(){try{predictions.value=(await request('/predictions')).predictions.reverse()}catch(e){error.value=e.message}}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`mmaofun-6.7-${name}-${value.id}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
watch(current,run=>{if(run){symbol.value=run.symbol;interval.value=run.interval;horizon.value=run.horizon}});watch(()=>route.query.run,()=>load());onMounted(load);onBeforeUnmount(()=>{disposed=true;clearTimeout(pollTimer)})
</script>

